func testCentroDeCustoToManyAddOpCDCDespesaCentroDeCustos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a CentroDeCusto
	var b, c, d, e DespesaCentroDeCusto

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, centroDeCustoDBTypes, false, strmangle.SetComplement(centroDeCustoPrimaryKeyColumns, centroDeCustoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*DespesaCentroDeCusto{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, despesaCentroDeCustoDBTypes, false, strmangle.SetComplement(despesaCentroDeCustoPrimaryKeyColumns, despesaCentroDeCustoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*DespesaCentroDeCusto{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddCDCDespesaCentroDeCustos(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.CDCID != first.CDCID {
			t.Error("foreign key was wrong value", a.CDCID, first.CDCID)
		}
		if a.CDCID != second.CDCID {
			t.Error("foreign key was wrong value", a.CDCID, second.CDCID)
		}

		if first.R.CDC != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.CDC != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.CDCDespesaCentroDeCustos[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.CDCDespesaCentroDeCustos[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.CDCDespesaCentroDeCustos().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}
